~~~go
func twoSum(nums []int, target int) (int, int, bool) {
    seen := make(map[int]int, len(nums))
    for i, value := range nums {
        if j, ok := seen[target-value]; ok { return j, i, true }
        seen[value] = i
    }
    return 0, 0, false
}
